import {esc,fmt} from '../../ui/format.js';
import {TYPES,FIELDS,PROCESS,POOLS,effective} from '../../core/model.js';
import {DIAGRAMS,expandedNeeds,modelAudit} from '../../core/mbse.js';
import {RELATIONS} from '../../core/model.js';
export function engineeringView(ctx){const {m,result,baseline,search}=ctx;const n=id=>m.nodes.find(n=>n.id===id);const findings=modelAudit(m);return `<div class="panelhead"><div><h1>MBSE & trasabilitate</h1><p>Un repository comun pentru cerințe, arhitectură, comportament și producție.</p></div><button data-action="audit-export">↓ Audit JSON</button></div><div class="notice">Subset editabil inspirat de SysML 1.7 / UML 2.5.1. Nu este o implementare conformă completă, certificare INCOSE sau înlocuitor integral Cameo. Numai relațiile de proces și alocările industriale intră în DES; diagramele comportamentale și parametrice documentează modelul.</div><div class="panel"><h2>Acoperire cerințe</h2><table><thead><tr><th>Cerință</th><th>Satisfăcută de</th><th>Verificată de</th></tr></thead><tbody>${m.nodes.filter(x=>x.type==='requirement').map(x=>`<tr><td>${esc(x.name)}</td>${['satisfies','verify'].map(t=>`<td>${m.edges.filter(e=>e.type===t&&e.to===x.id).map(e=>esc(n(e.from).name)).join(', ')||'—'}</td>`).join('')}</tr>`).join('')}</tbody></table><h3>Constatări · ${findings.length}</h3>${findings.map(f=>`<p>${esc(f.text)} <button data-open="${esc(f.id)}">Deschide</button></p>`).join('')||'<p>Nicio lipsă detectată de regulile implementate. Aceasta nu confirmă completitudinea modelului.</p>'}</div><div class="panel tablewrap"><h2>Registru diagrame & acoperire</h2><table><thead><tr><th>Diagramă</th><th>Referință</th><th>Suport</th><th>Conectori</th></tr></thead><tbody>${Object.values(DIAGRAMS).map(d=>`<tr><td>${esc(d.name)}</td><td>${esc(d.notation)}</td><td>${d.status==='executable'?'Executabil DES':d.status==='planned'?'Planificat · indisponibil':d.status==='generic'?'Editor generic':'Subset descriptiv editabil'}</td><td>${d.relations.map(k=>esc(RELATIONS[k])).join(', ')}</td></tr>`).join('')}</tbody></table><p>Nu sunt implementate import/export XMI, solver parametric, execuție UML, profiluri UAF/TOGAF complete sau extensii proprietare Airbus. Nivelurile MOFLT sunt metadate editabile.</p></div>`}
